const steps=[
 {id:"intro",label:"说明与授权",title:"确认已年满十八周岁",lead:"为了使用行程服务，需要完成身份证件核验和本人验证。",body:`<div class="card"><div class="row"><strong>身份证件核验</strong><span>确认出生日期与证件有效性</span></div><div class="row"><strong>本人验证</strong><span>活体检测与人脸一致性比对</span></div><div class="row"><strong>信息处理</strong><span>可能由经批准的第三方服务完成</span></div></div><div class="card warning"><strong>你的选择</strong><p>验证完成前，你仍可管理账户、查看隐私说明和提交申诉，但暂不能发起行程。</p></div>`,action:"我已阅读并继续"},
 {id:"front",label:"证件正面",title:"拍摄身份证人像面",lead:"摄像头会自动识别证件边框、清晰度和反光，无需手工输入。",body:`<div class="upload"><div class="camera-frame"><span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><div class="id-card"><small>中华人民共和国居民身份证</small><div class="avatar"></div><strong>姓名　合成用户</strong></div></div><p><strong style="color:var(--success)">已检测到证件 · 清晰度良好</strong><br><span>保持稳定，系统将自动拍摄并识别</span></p></div>`,action:"模拟自动拍摄"},
 {id:"back",label:"证件反面",title:"拍摄身份证国徽面",lead:"翻转证件后保持在取景框内，系统会自动读取有效期。",body:`<div class="upload"><div class="camera-frame"><span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><div class="id-card"><small>中华人民共和国居民身份证</small><h3 style="margin:28px 0 4px">国徽面</h3><small>有效期限 2024.01.01—2034.01.01</small></div></div><p><strong style="color:var(--success)">四角完整 · 无明显反光</strong><br><span>系统将自动完成拍摄和 OCR</span></p></div>`,action:"模拟自动拍摄"},
 {id:"confirm",label:"识别摘要",title:"核对自动识别摘要",lead:"以下内容由身份证 OCR 自动读取。若与证件不符，请返回重新拍摄，不能手工修改。",body:`<div class="card"><div class="row"><span>姓名</span><strong>合***</strong></div><div class="row"><span>证件号码</span><strong>310***********0007</strong></div><div class="row"><span>出生日期</span><strong>1996 年 8 月 12 日</strong></div><div class="row"><span>成年判定</span><strong style="color:var(--success)">已年满十八周岁</strong></div><div class="row"><span>法定性别</span><strong>♂</strong></div></div><div class="card warning"><strong>识别有误？</strong><p>请返回重新拍摄证件。法定字段不支持手工编辑。</p></div>`,action:"信息来自本人证件"},
 {id:"face",label:"本人验证",title:"完成本人验证",lead:"请在光线充足的环境中正对屏幕，按提示完成动作。",body:`<div class="camera">⌁</div><div class="card"><div class="check"><b>1</b><div><strong>活体检测</strong><br><span>确认当前由真实本人操作</span></div></div><div class="check"><b>2</b><div><strong>人脸一致性</strong><br><span>与证件头像进行一次性比对</span></div></div></div>`,action:"开始合成本人验证"},
 {id:"submit",label:"自动核验",title:"正在完成自动核验",lead:"外部身份服务正在处理证件、成年判定、活体和人脸一致性结果。",body:`<div class="card checklist"><div class="check"><b>✓</b><div><strong>身份证件</strong><br><span>OCR、真实性与有效期通过</span></div></div><div class="check"><b>✓</b><div><strong>成年判定</strong><br><span>已确认年满十八周岁</span></div></div><div class="check"><b>✓</b><div><strong>活体检测</strong><br><span>自动检测通过</span></div></div><div class="check"><b>…</b><div><strong>人脸一致性</strong><br><span>正在等待明确结果</span></div></div></div><div class="card"><strong>无需人工批准</strong><p>四项检查全部通过后，系统会自动开放业务能力。结果未知时继续保持关闭并允许重试。</p></div>`,action:"查看自动结果"},
 {id:"processing",label:"结果处理中",title:"正在等待自动结果",lead:"无需停留在本页。结果返回后会自动更新并通过任务中心通知。",body:`<div class="timeline"><div class="timeline-item"><i class="dot"></i><div><strong>摄像头采集完成</strong><br><span>今天 09:41</span></div></div><div class="timeline-item"><i class="dot"></i><div><strong>证件、成年与活体通过</strong><br><span>今天 09:42</span></div></div><div class="timeline-item current"><i class="dot"></i><div><strong>等待人脸一致性结果</strong><br><span>业务准入继续保持关闭</span></div></div></div><div class="card warning" style="margin-top:20px"><strong>结果未知时</strong><p>系统不会自动重复上传人脸材料。你可以稍后查询，或在明确失败后重新进行指定步骤。</p></div>`,action:"返回首页",secondary:"查看补充材料示例"},
 {id:"more",label:"补充材料",title:"需要重新提交证件正面",lead:"审核发现人像面有反光，姓名和出生日期无法完整识别。",body:`<div class="card danger"><strong>需要补充</strong><p>只需重新完成“证件正面”，其他步骤已保留。</p></div><div class="upload"><div class="id-card" style="filter:blur(1px);opacity:.55"><small>反光示例</small><div class="avatar"></div></div><p><strong>避免顶部灯光反射</strong><br><span>将证件平放后重新拍摄</span></p></div>`,action:"重新上传正面"},
 {id:"verified",label:"验证通过",title:"成年资格已确认",lead:"你的账户现在可以使用行程服务。",body:`<div class="result"><div><div class="result-mark">✓</div><h2>验证已完成</h2><p>无需再次查看验证进度或刷新状态。若验证结果失效，我们会明确说明原因和下一步。</p></div></div>`,action:"进入首页"}
];
let current=0;
const nav=document.querySelector("#nav"),list=document.querySelector("#step-list"),screen=document.querySelector("#screen");
function render(){
 const step=steps[current];
 nav.innerHTML=steps.map((s,i)=>`<button class="${i===current?"active":""}" data-i="${i}">${s.label}</button>`).join("");
 list.innerHTML=steps.slice(0,6).map((s,i)=>`<li data-index="${i+1}" class="${i<current?"done":i===current?"active":""}">${s.label}</li>`).join("");
 const bars=steps.slice(0,6).map((_,i)=>`<span class="${i<=Math.min(current,5)?"on":""}"></span>`).join("");
 screen.innerHTML=`<div class="app-head"><button class="back">‹</button><span class="sandbox">◇ 内部沙箱</span></div><div class="progress">${bars}</div><div class="eyebrow">${step.label}</div><h2 class="screen-title">${step.title}</h2><p class="lead">${step.lead}</p>${step.body}<div class="actions"><button class="primary">${step.action}</button>${step.secondary?`<button class="secondary">${step.secondary}</button>`:""}<div class="hint">仅用于设计评审，不上传真实身份材料</div></div>`;
 document.querySelectorAll("[data-i]").forEach(b=>b.onclick=()=>{current=Number(b.dataset.i);render()});
 screen.querySelector(".back").onclick=()=>{if(current>0){current--;render()}};
 screen.querySelector(".primary").onclick=()=>{if(current<steps.length-1){current++;render()}};
 if(step.secondary)screen.querySelector(".secondary").onclick=()=>{current=7;render()};
}
render();
